// Local build coordinator. App edits are generated by Groq, restricted to Studio.
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const env = {};
for (const line of (await fs.readFile(path.join(root, '.env'), 'utf8')).split(/\r?\n/)) { const m = line.match(/^\s*([A-Z_]+)\s*=\s*(.*)$/); if (m) env[m[1]] = m[2].replace(/^["']|["']$/g, ''); }
const app = await fs.readFile(path.join(root, 'studio/public/app.js'), 'utf8');
const server = await fs.readFile(path.join(root, 'studio/server.mjs'), 'utf8');
const task = process.argv[2] || 'research';
const codingModel = 'groq/qwen/qwen3.8-27b';
const section = (text, start, end) => { const i = text.indexOf(start), j = text.indexOf(end, i + start.length); if (i < 0 || j < 0) throw new Error('Missing context anchor'); return text.slice(i, j); };
const common = `Finish the Vietnamese local Tich Studio application per user screenshot requirements. You are the coding model. Produce small exact search/replace edits, no full rewrites. Preserve existing unrelated functionality and routes. Never add secrets, packages, external runtime dependencies, or pretend services work. No remote webpage execution. All dynamic text must use esc. Do not add inline handlers because CSP disallows them. Event actions go in handle switch. Only allowed files: studio/public/app.js, studio/server.mjs, studio/public/style.css, studio/README.md. Output JSON {"summary":"...","edits":[{"file":"...","search":"exact original unique text","replace":"new code"}]}. Each search must exactly match provided text and occur exactly once. No placeholders. Keep edits compact and syntactically valid. Do not close a function when replacing a partial prefix; retain original brace balance. User wants Groq to author the app code. Do not use OpenAI endpoints directly: all app inference goes through configured OmniRoute Groq model.\n`;
const tasks = {
 persistence: {
 request: `Fix small reliability defects with tiny edits: state PUT must return await task so route try/catch handles rejected promises; frontend narration change invalidate approvals/assetsStale BEFORE calling setBinding, preserve previousNarration; saveQueue failures block future writes until reload using boolean flag, and catch rethrows. Add .catch(()=>{}) to fire-and-forget save in setBinding to prevent unhandled rejection, but do not clear failure flag. Under800 tokens.`,
 context: section(server,"      if (url.pathname === '/api/state' && req.method === 'PUT')","      if (url.pathname === '/api/settings' && req.method === 'GET')")+'\n'+section(app,'function save()','function activity')+'\n'+section(app,'function setBinding','async function run')+'\n'+section(app,"  if(el.dataset.bind)","  if(el.dataset.channelSelect)"),
 },
 references: {
 request: `Add one helper function deriveReferences(p) immediately before async function handle. Count distinct scenes per normalized scene.characters names and scene.background, character threshold3 background4; preserve existing p.references image/prompt by stable id, assign safe stable ASCII filenames character-001.png background-001.png; descriptions from first matching visual. Return references and save on caller later, helper only no UI integration yet. Also insert action case 'derive-references' immediately before case 'export-project': set p.references=deriveReferences(p), await save, render. Tiny edits <800 output tokens.`,
 context: 'async function handle(action,el){const s=currentSurvey(),c=currentChannel(),p=currentProject();switch(action){\n'+section(app,"case 'export-project':","case 'finish-project':"),
 },
 schemafix: {
 request: `Add research schema fields already expected by frontend: summary string, timeline [{date,event,sourceId}], facts [{value,claim,sourceId,status}], sensory string, cast [{name,role,sourceId}], angles array of three strings, preserving claims/questions. Directives research must ask compact results sourced only supplied text. Scenes schema add characters array of name strings and background name string; directive same. Reduce generateScenes batch8 to2. At most4 tiny exact edits, under850 tokens.`,
 context: section(server,'  research:','};')+'\n'+section(server,'      research:','    };')+'\n'+section(app,'async function generateScenes','async function handle'),
 },
 smallfix: {
 request: `Fix three obvious frontend defects with tiny exact edits: select-angle handler uses undefined e, change to el and await save before render; thumbnailVisual input data-field must use data-bind; save catch should rethrow, so success not claimed after failed persistence. Do not change anything else. Output under700 tokens.`,
 context: section(app,"case 'select-angle':","case 'approve-next':")+'\n'+section(app,'function save()','function activity')+'\n'+section(app,'function thumbnailEditor','function drawThumbnail'),
 },
 quota: {
 request: `Fix request sizes for Groq free-rate compatibility: default output maxTokens2200, script3500, scenes2500, others2200. Cap serialized context to18000 characters with explicit failure asking to shorten source or use smaller batches, never silently truncate. Default settings model Groq regardless of global env model, and settings PUT only permits groq/ prefix because user requires Groq only. Do not touch API credentials. At most4 small edits.`,
 context: section(server,'let settings','let state')+'\n'+section(server,'async function ai','async function youtube')+'\n'+section(server,'    const response = await ai','    if (b.action')+'\n'+section(server,"      if (url.pathname === '/api/settings' && req.method === 'PUT')","      if (url.pathname === '/api/test'"),
 },
 assets: {
 request: `Extend stages 6 and 7 to match screenshot workflow. Derive recurring character references only when character appears in at least 3 scenes, background references at least 4 scenes, based on explicit scene.characters and scene.background fields (do not infer fictional counts). Add reference list with stable safe filename, editable English prompt, individual image upload using existing data URL approach; export reference prompts TXT with filenames. Add scene count and missing image count, multi-image upload matched by scene-001 filenames with no ambiguous auto mapping; each file max2MB and whole batch max8MB because state API14MB body. Reject overflow clearly. Add optional 4/6/8-second clip prompt groups using scene duration, export prompts TXT each group. Explain clip creation happens externally; do not call G-Labs. Keep generated prompt reference filename for selected characters/background. Correct thumb-visual data-field to data-bind. Do not add video binary uploads yet. Preserve existing single scene upload and character sheet locks. Produce at most 6 compact edits. Helper functions can be inserted immediately before async function handle. Add new actions before case export-project. Upload branches may be inserted early in change listener and return so existing image handling is retained.`,
 context: section(app,'if(p.step===5)','if(p.step===7)')+'\n'+section(app,'function promptText','function markdownProject')+'\n'+section(app,'async function handle','switch(action){')+'switch(action){\n'+section(app,"case 'export-project':","case 'finish-project':")+'\n'+section(app,"app.addEventListener('change'","app.addEventListener('input'")+'\n'+section(app,'function thumbnailEditor','function drawThumbnail'),
 },
 research: {
  request: `Add richer Research matching screenshots: editable summary, timeline events with date and sourceId, numerical facts with sourceId and check status, sensory details, cast, three proposed narrative angles plus user custom angle. Research must only extract from supplied source text, not pretend URLs were read. Preserve claims and questions. Select one research angle via button, persist project.researchAngle, feed it to script/outline via projectContext. Render all supplied text safely. Add concise quality note in script: estimated word count, no false retention scores. Handle incomplete output arrays gracefully.`,
  context: section(app,'function projectContext','function workshop') + '\n' + section(app,'if(p.step===2)','if(p.step===4)') + '\n' + section(app,"case 'research':","case 'copy-script':") + '\nSERVER SCHEMA: ' + section(server,"  research:","  scenes:") + '\nSERVER TASK: ' + section(server,"      research:","      scenes:"),
 },
 thumbnails: {
  request: `Improve thumbnail and title workflow per screenshots. Generate 16 title variations on request, not 3. Use selected channel thumbnail layout and make overlay direct edit. Add a separate field project.thumbnailVisual (English scene prompt), use it in copy-thumbnail, and pass selected thumbnail/promise in future writing. Default editor-owned text, no text baked into image. Add thumbnail character/style lock in copied prompt only when mascot has character sheet. Add discard title set button with confirmation and invalidate approval on replacing titles. Preserve manual input and export. Add compact note that dates/numbers require source and Groq only generates text prompts, not images. No invented cost.`,
  context: section(app,'if(p.step===1)','if(p.step===2)') + '\n' + section(app,'function thumbnailEditor','function drawThumbnail') + '\n' + section(app,"case 'packaging':","case 'add-source':") + '\n' + section(app,"case 'copy-thumbnail':","case 'export-thumbnail':") + '\nSERVER: ' + section(server,"      packaging:","      research:"),
 },
 reliability: {
  request: `Audit and fix specific reliability problems. State PUT races can let stale revision writes interleave; serialize state revision check + atomic write and commit as one operation using a dedicated queue without deadlocking atomicSave queue. Frontend save() currently catches failure and claims success; prevent later writes after revision conflict and show clear reload instruction instead of clobbering data. Narration change currently save happens before approval invalidation; fix persistence ordering. If project.assetsStale, prominently show a warning on workshop scenes and packaging and require explicit clear-old-scenes action with confirmation before continuing scene generation; preserve previousNarration and no auto-delete. Validate minutes target (positive <=60) before script and scene generation. Do not change credential settings.`,
  context: section(app,'function save()','function activity') + '\n' + section(app,'async function generateScenes','async function handle') + '\n' + section(app,'app.addEventListener(\'change\'','app.addEventListener(\'input\'') + '\n' + section(app,'function workshop','if(p.step===0)') + '\nSERVER: ' + section(server,"      if (url.pathname === '/api/state' && req.method === 'PUT')","      if (url.pathname === '/api/settings' && req.method === 'GET')") + '\nSERVER QUEUE: ' + section(server,'let storageQueue','const cache'),
 },
};
tasks.reliability.request = `Only fix server state PUT race: separate stateMutationQueue initialized next to storageQueue, serialize revision check, atomicSave, state commit and response inside that queue; return from route. Use at most2 edits and <800 output tokens. Do not modify frontend.`;
tasks.reliability.context = section(server,"      if (url.pathname === '/api/state' && req.method === 'PUT')","      if (url.pathname === '/api/settings' && req.method === 'GET')")+'\n'+section(server,'let storageQueue','const cache');
tasks.quota.request = `Only change output limits: default ai maxTokens700, script900, scenes900, all others700. Default model hardcode groq/qwen/qwen3.8-27b instead of global env model. At most3 small edits, <600 output tokens. Do not change anything else.`;
if (!tasks[task]) throw new Error('Unknown build task');
if(task==='references')tasks.references.request += ` Context fragments are NOT adjacent. First edit search ONLY the exact async function handle prefix (without export case), replace helper plus unchanged prefix. Second edit search ONLY case 'export-project': and prepend new action. Count each name once per scene with Set, preserve existing refs by type+normalized name rather than ordinal id.`;
console.log(`Groq coding task: ${task}`);
let result;
for (let attempt = 0; attempt < 3; attempt++) {
 const res = await fetch(env.OPENAI_BASE_URL.replace(/\/+$/, '') + '/chat/completions', { method: 'POST', headers: { 'Content-Type':'application/json', Authorization:'Bearer '+env.OPENAI_API_KEY }, body: JSON.stringify({ model: codingModel, reasoning_effort:'none', response_format:{type:'json_object'}, max_tokens:1000, temperature:0.2, stream:false, messages:[{role:'system',content:common},{role:'user',content:tasks[task].request+'\nCURRENT EXACT SOURCE CONTEXT:\n'+tasks[task].context}]}), signal:AbortSignal.timeout(120000)});
 const data = await res.json();
 if(res.status===429 && attempt<2){console.log('Groq rate limit; waiting 30 seconds.');await new Promise(r=>setTimeout(r,30000));continue;}
 if(!res.ok){const message=String(data.error?.message||data.message||'').replace(/(?:gsk_|sk-|AIza)[A-Za-z0-9_-]+/g,'[REDACTED]');console.log(JSON.stringify({status:res.status,code:data.error?.code||'request-failed',message:message.slice(0,700)}));process.exit(1);}
 try { result=JSON.parse(data.choices[0].message.content); } catch { console.log('Groq returned invalid patch JSON.');process.exit(1); }
 console.log(JSON.stringify({model:data.model,tokens:data.usage?.total_tokens,editCount:result.edits?.length}));break;
}
if(!result?.edits?.length)throw new Error('No edits returned');
await fs.mkdir(path.join(root,'.studio-data','build'),{recursive:true});
await fs.writeFile(path.join(root,'.studio-data','build',`${task}-proposal.json`),JSON.stringify(result,null,2));
const allowed=new Set(['studio/public/app.js','studio/server.mjs','studio/public/style.css','studio/README.md']);
const originals=new Map(),updates=new Map();
for(const edit of result.edits){
 if(!allowed.has(edit.file)||typeof edit.search!=='string'||!edit.search||typeof edit.replace!=='string')throw new Error('Invalid edit');
 const absolute=path.join(root,edit.file);if((await fs.lstat(absolute)).isSymbolicLink())throw new Error('Symlink target refused');
 if(!originals.has(edit.file)){const text=await fs.readFile(absolute,'utf8');originals.set(edit.file,text);updates.set(edit.file,text);}
 const source=updates.get(edit.file),first=source.indexOf(edit.search);
 if(first<0||source.indexOf(edit.search,first+edit.search.length)>=0)throw new Error('Patch anchor not unique: '+edit.file);
 updates.set(edit.file,source.slice(0,first)+edit.replace+source.slice(first+edit.search.length));
}
const dir=path.join(root,'.studio-data','build');await fs.mkdir(dir,{recursive:true});
for(const [file,text] of updates){if(file.endsWith('.js')||file.endsWith('.mjs')){const temp=path.join(dir,file.replaceAll('/','_')+(file.endsWith('.mjs')?'.mjs':'.js'));await fs.writeFile(temp,text);const check=spawnSync(process.execPath,['--check',temp],{encoding:'utf8'});if(check.status!==0){console.log('Generated patch failed syntax check: '+file);process.exit(1);}}}
await fs.writeFile(path.join(dir,`${task}-${Date.now()}.json`),JSON.stringify({model:codingModel,summary:result.summary,edits:result.edits},null,2));
for(const [file,text] of updates)await fs.writeFile(path.join(root,file),text);
console.log('Groq edits applied after exact-match and syntax checks.');
